// Whether a file is generated, read off the house markers alone: the header a generator writes as its output's first
// line (`// GENERATED by <generator>`, or the same after `/*` or `/**`), or a `.gen.` infix in the file name. Each
// generator spells its own header, as packages/ui/tokens.build.ts does, since no package may import tooling.
const GENERATED_INFIX = /\.gen\.[^./]+$/u;
const GENERATED_HEADER = /^(?:\/\/|\/\*\*?) GENERATED by /u;

/** The opening text {@link isGeneratedFile} reads: the header sits on the first line, and a longer one is no header. */
export const GENERATED_HEAD_CHARS = 512;

/** Whether the file at `path` is generated. `readHead` gives the file's opening text and runs only when the name
 *  decides nothing. */
export function isGeneratedFile(path: string, readHead: () => string): boolean {
  return GENERATED_INFIX.test(path) || GENERATED_HEADER.test(readHead().slice(0, GENERATED_HEAD_CHARS));
}
